(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.019-t*0.27)*18 + Math.sin(x*0.016+t*0.33)*12;
  const w2x = Math.sin(x*0.009-t*0.15)*25 + Math.cos(y*0.011+t*0.12)*20;
  const w2y = Math.cos(y*0.008+t*0.18)*25 + Math.sin(x*0.01-t*0.14)*20;
  const sx = x + w1x + w2x*0.4, sy = y + w1y + w2y*0.4;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1],
    [400+Math.cos(t*0.38+6)*60, 200+Math.sin(t*0.72)*55, 0.065, 2.4],
    [200+Math.sin(t*0.55+1.5)*110, 220+Math.cos(t*0.42+2.5)*40, 0.085, 1.8]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    harm += Math.sin(d*f*1.618 - t*sp*1.3 + 0.7)*0.5;
  }
  const act = aS/9, inh = iS/9, hrm = harm/9;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = (Math.sin(dist*0.033-ang*5+t*0.9) + Math.sin(dist*0.025+ang*2.5-t*0.7))*0.25;
  const pulse = Math.sin(dist*0.06 - t*3)*Math.exp(-dist*0.005)*0.3;
  const moire = Math.sin((sx*0.07+sy*0.05)*Math.sin(t*0.2)*0.5+1)*Math.cos((sx*0.05-sy*0.08)*Math.cos(t*0.15)*0.5)*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral1)*2.2);
  const rd2 = Math.tanh((hrm*1.2 - act*0.5 + spiral2 + moire)*1.8);
  const reaction = rd1*0.65 + rd2*0.35;
  const blend = reaction*0.7 + cell*0.3;
  const v = blend*0.5+0.5;
  const vign = 1.0 - Math.pow(dist/300, 2)*0.25;
  const pal = [[5,12,52],[12,45,95],[18,90,120],[25,145,130],[60,175,110],[180,190,60],[220,150,50],[200,90,60],[160,50,70],[90,25,60],[40,15,55],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = (0.8+Math.sin(reaction*Math.PI)*0.2)*vign;
  const edge = Math.abs(reaction)>0.65?1.12:Math.abs(reaction)<0.15?0.88:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
